def predict_transform_v3(input_grid):
    """Transform based on being between uniform rows"""
    import copy
    output = copy.deepcopy(input_grid)

    h, w = len(input_grid), len(input_grid[0])

    for r in range(h):
        # Get the cell's value
        row_vals = input_grid[r]
        if not all(v == row_vals[0] for v in row_vals):
            continue

        val = row_vals[0]

        # Condition 2: Target row must be between two uniform rows of same value
        if r > 0 and r < h - 1:
            above_val = input_grid[r-1][0]
            below_val = input_grid[r+1][0]

            if above_val == below_val == val:
                for c in range(w):
                    count_3 = sum(1 for rr in range(h) if input_grid[rr][c] == 3)

                    if count_3 == 1:
                        output[r][c] = 1

    return output

