def predict_transform_v11(input_grid):
    """Use count to determine marker: fewer total appearances = marker"""
    import copy
    output = copy.deepcopy(input_grid)

    h, w = len(input_grid), len(input_grid[0])

    # Count occurrences of each value across entire grid
    val_counts = {}
    for r in range(h):
        for c in range(w):
            v = input_grid[r][c]
            val_counts[v] = val_counts.get(v, 0) + 1

    print(f"Value counts: {val_counts}")

    # Find mixed row
    for mr in range(h):
        distinct = set(input_grid[mr])

        if len(distinct) == 2:
            v1, v2 = sorted(list(distinct))

            # Heuristic: lower count = marker (rarer is more special)
            if val_counts[v1] < val_counts[v2]:
                marker_val, target_val = v1, v2
            else:
                marker_val, target_val = v2, v1

            print(f"Mixed row {mr}: marker={marker_val}, target={target_val}")

            # Apply transformation
            for c in range(w):
                val = input_grid[mr][c]

                if val == target_val:
                    count_marker = sum(1 for rr in range(h) if input_grid[rr][c] == marker_val)

                    if count_marker == 1:
                        output[mr][c] = 1

    return output

